const test = require('node:test');
const assert = require('node:assert/strict');
const { execution, batch, settle } = require('./query-load-more-harness.js');
const { createQueryBrowserHarness } = require('./query-browser-harness.js');

const WORKBENCH_PATH = '/rdf4j-workbench';
const TOKEN_COOKIE = 'rdf4j-workbench-csrf';

function installPathAwareCookies(document, options = {}) {
    const workbenchPath = options.workbenchPath || WORKBENCH_PATH;
    const cookies = [
        ...(options.tokenCookies || [
            { name: TOKEN_COOKIE, value: 'a'.repeat(64), path: workbenchPath },
            { name: TOKEN_COOKIE, value: 'b'.repeat(64), path: '/' }
        ]),
        { name: 'workbench-preference', value: 'keep', path: workbenchPath },
        { name: 'server-user-password', value: 'keep', path: workbenchPath, httpOnly: true },
        { name: 'workbench-session', value: 'keep', path: '/', httpOnly: true }
    ];

    function pathMatches(requestPath, cookiePath) {
        if (cookiePath === '/') {
            return true;
        }
        return requestPath === cookiePath || requestPath.startsWith(cookiePath.endsWith('/')
            ? cookiePath : cookiePath + '/');
    }

    Object.defineProperty(document, 'cookie', {
        configurable: true,
        get() {
            return cookies.filter(cookie => !cookie.httpOnly && pathMatches(document.location.pathname, cookie.path))
                .sort((left, right) => right.path.length - left.path.length)
                .map(cookie => cookie.name + '=' + cookie.value)
                .join('; ');
        },
        set(value) {
            const [pair, ...attributes] = String(value).split(';').map(attribute => attribute.trim());
            const separator = pair.indexOf('=');
            if (separator < 0) {
                return;
            }
            const name = pair.substring(0, separator);
            const cookieValue = pair.substring(separator + 1);
            const pathAttribute = attributes.find(attribute => /^path=/i.test(attribute));
            const path = pathAttribute ? pathAttribute.substring(pathAttribute.indexOf('=') + 1) : '/';
            const maxAgeAttribute = attributes.find(attribute => /^max-age=/i.test(attribute));
            const expired = maxAgeAttribute && Number(maxAgeAttribute.substring(maxAgeAttribute.indexOf('=') + 1)) <= 0;
            for (let index = cookies.length - 1; index >= 0; index--) {
                if (cookies[index].name === name && cookies[index].path === path) {
                    cookies.splice(index, 1);
                }
            }
            if (!expired) {
                cookies.push({ name, value: cookieValue, path });
            }
        }
    });

    return {
        has(name, path) {
            return cookies.some(cookie => cookie.name === name && cookie.path === path);
        },
        value(name, path) {
            return cookies.find(cookie => cookie.name === name && cookie.path === path)?.value;
        }
    };
}

function rejectCookieWrites(document) {
    const descriptor = Object.getOwnPropertyDescriptor(document, 'cookie');
    Object.defineProperty(document, 'cookie', {
        configurable: true,
        get: descriptor.get,
        set() {
            throw new Error('Cookie access is unavailable');
        }
    });
}

function mountWorkbench(document, options = {}) {
    const contextPath = options.contextPath || '';
    const basePath = options.basePath || WORKBENCH_PATH;
    const pagePath = options.pagePath || basePath + '/repositories/test/query';
    document.location.href = 'http://localhost:8080' + pagePath;
    let mount = document.getElementById('workbench-app');
    if (!mount) {
        mount = document.createElement('div');
        mount.setAttribute('id', 'workbench-app');
        document.body.appendChild(mount);
    }
    mount.setAttribute('data-workbench-context-path', contextPath);
    mount.setAttribute('data-workbench-base-path', basePath);
}

function httpErrorResponse(status, options = {}) {
    const statusText = options.statusText || (status === 403 ? 'Forbidden' : 'Internal Server Error');
    const body = options.body === undefined
        ? (status === 403 ? 'Request integrity validation failed' : 'Server error response') : options.body;
    const contentType = options.contentType === undefined ? 'text/html;charset=utf-8' : options.contentType;
    return Promise.resolve({
        ok: false,
        status,
        statusText,
        headers: { get: name => name === 'Content-Type' ? contentType : null },
        text: () => Promise.resolve(contentType && /html/i.test(contentType)
            ? '<html><body>' + body + '</body></html>' : String(body))
    });
}

function assertForbiddenGuidance(message, action, detail) {
    for (const text of [
        'Workbench could not ' + action + ' (HTTP 403 Forbidden).',
        'Refresh this page and try again.',
        'If the error persists, clear the cookies for this Workbench site in your browser settings, then refresh the page and try again.'
    ]) {
        assert.ok(message.includes(text), 'expected forbidden guidance to include: ' + text + '\nActual: ' + message);
    }
    if (detail) {
        assert.ok(message.includes(detail), 'expected useful server detail in: ' + message);
    }
}

test('query 403 clears only the stale mount cookie and a user retry succeeds', async () => {
    const current = execution({
        responses: [
            (url, init) => {
                assert.equal(init.headers['X-RDF4J-CSRF-Token'], 'a'.repeat(64),
                    'the more-specific M2 cookie is the token sent on the first request');
                return httpErrorResponse(403);
            },
            batch([1], 0, false)
        ]
    });
    mountWorkbench(current.document);
    const cookies = installPathAwareCookies(current.document);
    current.form.setAttribute('action', WORKBENCH_PATH + '/repositories/test/query');

    try {
        current.controller.submit();
        await settle();

        assert.equal(current.requests.length, 1, 'the rejected request is not retried automatically');
        assertForbiddenGuidance(current.target.querySelector('.query-result-error__message').textContent,
            'execute the query', 'Request integrity validation failed');
        assert.equal(cookies.has(TOKEN_COOKIE, WORKBENCH_PATH), false,
            'the obsolete mount-scoped token is expired');
        assert.equal(cookies.value(TOKEN_COOKIE, '/'), 'b'.repeat(64), 'the current context token remains available');
        assert.equal(cookies.value('workbench-preference', WORKBENCH_PATH), 'keep');
        assert.equal(cookies.value('server-user-password', WORKBENCH_PATH), 'keep');
        assert.equal(cookies.value('workbench-session', '/'), 'keep');

        current.controller.submit();
        await settle();

        assert.equal(current.requests.length, 2, 'a retry happens only after the user submits again');
        assert.equal(current.requests[1].init.headers['X-RDF4J-CSRF-Token'], 'b'.repeat(64));
        assert.equal(current.workers[current.workers.length - 1].rows[0][0].value, '1');
    } finally {
        current.controller.dispose();
    }
});

test('explain 403 clears the stale cookie, shows the error, and allows an explicit retry', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1', 'request-2'] });
    mountWorkbench(harness.document);
    const cookies = installPathAwareCookies(harness.document);

    harness.runPageLoad();
    harness.context.workbench.query.runExplain('Optimized', 'explain-trigger');
    const rejected = harness.pendingExplainRequests[0];
    rejected.jqXHR.status = 403;
    rejected.jqXHR.responseJSON = {
        error: { code: 'FORBIDDEN' },
        message: 'Request integrity validation failed'
    };
    rejected.reject('error', 'Forbidden');

    assert.equal(harness.pendingExplainRequests.length, 1, 'the forbidden request is not retried automatically');
    assertForbiddenGuidance(harness.getText('query-explanation-status'), 'generate the explanation',
        'Request integrity validation failed');
    assert.equal(cookies.has(TOKEN_COOKIE, WORKBENCH_PATH), false);
    assert.equal(cookies.value(TOKEN_COOKIE, '/'), 'b'.repeat(64));

    harness.context.workbench.query.runExplain('Optimized', 'explain-trigger');
    const retry = harness.pendingExplainRequests[1];
    assert.ok(retry, 'the user can request another explanation after cleanup');
    retry.resolve({ content: 'Projection', format: 'text', error: '' });
    assert.notEqual(harness.getText('query-explanation-status'), 'Request integrity validation failed');
});

test('compare explain 403 clears a stale mount cookie', () => {
    const harness = createQueryBrowserHarness({
        serverRequestIds: ['request-1'],
        initialExplanation: 'Initial plan',
        initialExplanationFormat: 'text',
        query: 'SELECT * WHERE {?s ?p ?o}'
    });
    mountWorkbench(harness.document);
    const cookies = installPathAwareCookies(harness.document);

    harness.runPageLoad();
    harness.context.workbench.query.toggleCompareMode();
    assert.equal(harness.pendingExplainRequests.length, 1, 'opening Compare requests its initial explanation');
    const rejected = harness.pendingExplainRequests[0];
    rejected.jqXHR.status = 403;
    rejected.jqXHR.responseText = JSON.stringify({ error: 'Forbidden' });
    rejected.reject('error', 'Forbidden');

    assert.equal(cookies.has(TOKEN_COOKIE, WORKBENCH_PATH), false);
    assert.equal(cookies.value(TOKEN_COOKIE, '/'), 'b'.repeat(64));
    const errorMessage = harness.getText('query-explanation-status-compare');
    assertForbiddenGuidance(errorMessage, 'generate the explanation');
    assert.equal(errorMessage.endsWith('Forbidden'), false,
        'the generic structured status does not repeat the Forbidden title');
});

test('non-403 query failures do not clear the stale cookie', async () => {
    const current = execution({ responses: [() => httpErrorResponse(500)] });
    mountWorkbench(current.document);
    const cookies = installPathAwareCookies(current.document);
    current.form.setAttribute('action', WORKBENCH_PATH + '/repositories/test/query');

    try {
        current.controller.submit();
        await settle();

        assert.match(current.target.querySelector('.query-result-error__message').textContent, /HTTP 500/);
        assert.equal(cookies.value(TOKEN_COOKIE, WORKBENCH_PATH), 'a'.repeat(64));
        assert.equal(current.requests.length, 1);
    } finally {
        current.controller.dispose();
    }
});

